dashboard.definition:
{
    "dataSources": {
        "ds_cve_search": {
            "type": "ds.search",
            "options": {
                "query": "`cveicu_index` sourcetype=\"cveicu:record\"\n| spath cveMetadata.cveId\n| spath cveMetadata.state\n| spath cveMetadata.datePublished\n| spath containers.cna.title\n| spath containers.cna.affected{0}.vendor\n| spath containers.cna.affected{0}.product\n| spath containers.cna.metrics{0}.cvssV3_1.baseScore\n| spath containers.cna.metrics{0}.cvssV3_1.baseSeverity\n| spath containers.cna.metrics{0}.cvssV4_0.baseScore\n| spath containers.cna.metrics{0}.cvssV4_0.baseSeverity\n| spath containers.cna.problemTypes{0}.descriptions{0}.cweId\n| rename \"cveMetadata.cveId\" as cve_id, \"cveMetadata.state\" as state, \"cveMetadata.datePublished\" as date_published, \"containers.cna.title\" as title, \"containers.cna.affected{0}.vendor\" as vendor, \"containers.cna.affected{0}.product\" as product, \"containers.cna.metrics{0}.cvssV3_1.baseScore\" as cvss_v31_score, \"containers.cna.metrics{0}.cvssV3_1.baseSeverity\" as cvss_v31_severity, \"containers.cna.metrics{0}.cvssV4_0.baseScore\" as cvss_v40_score, \"containers.cna.metrics{0}.cvssV4_0.baseSeverity\" as cvss_v40_severity, \"containers.cna.problemTypes{0}.descriptions{0}.cweId\" as cwe_id\n| eval cvss_score=coalesce(cvss_v40_score, cvss_v31_score)\n| eval severity=coalesce(cvss_v40_severity, cvss_v31_severity, \"NONE\")\n| where state=\"PUBLISHED\"\n| search $vendor_filter$ $severity_filter$ $cwe_filter$\n| table cve_id title vendor product cvss_score severity cwe_id date_published\n| sort - date_published",
                "queryParameters": {
                    "earliest": "$time_range.earliest$",
                    "latest": "$time_range.latest$"
                }
            }
        },
        "ds_ingest_sparkline": {
            "type": "ds.search",
            "options": {
                "query": "`cveicu_index` sourcetype=\"cveicu:record\"\n| timechart span=1d count",
                "queryParameters": {
                    "earliest": "-30d@d",
                    "latest": "now"
                }
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-7d@d",
                        "latest": "now"
                    }
                }
            }
        }
    },
    "inputs": {
        "input_time_range": {
            "type": "input.timerange",
            "options": {
                "token": "time_range",
                "defaultValue": "-7d@d,now"
            },
            "title": "Time Range"
        },
        "input_vendor": {
            "type": "input.text",
            "options": {
                "token": "vendor_filter",
                "defaultValue": "*"
            },
            "title": "Vendor"
        },
        "input_severity": {
            "type": "input.dropdown",
            "options": {
                "token": "severity_filter",
                "defaultValue": "*",
                "items": [
                    {"label": "All", "value": "*"},
                    {"label": "Critical", "value": "severity=CRITICAL"},
                    {"label": "High", "value": "severity=HIGH"},
                    {"label": "Medium", "value": "severity=MEDIUM"},
                    {"label": "Low", "value": "severity=LOW"}
                ]
            },
            "title": "Severity"
        },
        "input_cwe": {
            "type": "input.text",
            "options": {
                "token": "cwe_filter",
                "defaultValue": "*"
            },
            "title": "CWE ID"
        }
    },
    "layout": {
        "type": "grid",
        "options": {"width": 1440},
        "structure": [
            {"item": "viz_ingest_sparkline", "type": "block", "position": {"x": 0, "y": 0, "w": 1440, "h": 200}},
            {"item": "viz_cve_table", "type": "block", "position": {"x": 0, "y": 200, "w": 1440, "h": 600}}
        ],
        "globalInputs": ["input_time_range", "input_vendor", "input_severity", "input_cwe"]
    },
    "visualizations": {
        "viz_ingest_sparkline": {
            "type": "splunk.line",
            "dataSources": {"primary": "ds_ingest_sparkline"},
            "title": "Ingestion Volume (Last 30 Days)",
            "options": {"xAxisTitleText": "Date", "yAxisTitleText": "CVEs Ingested"}
        },
        "viz_cve_table": {
            "type": "splunk.table",
            "dataSources": {"primary": "ds_cve_search"},
            "title": "CVE Records",
            "options": {"count": 20}
        }
    },
    "title": "CVE Explorer",
    "description": "Search and filter CVE records from the CVE List V5 database"
}
